pub fn import_from_local(
    state: &AppState,
    v: &OmoVariant,
) -> Result<crate::provider::Provider, AppError> {
    let location = Self::resolve_local_config_location(v)?;
    let obj = Self::read_config_object(&location)?;

    let mut settings = Map::new();
    if let Some(agents) = obj.get("agents") {
        settings.insert("agents".to_string(), agents.clone());
    }
    if v.has_categories {
        if let Some(categories) = obj.get("categories") {
            settings.insert("categories".to_string(), categories.clone());
        }
    }

    let other = Self::extract_other_fields_with_keys(&obj, &["agents", "categories"]);
    if !other.is_empty() {
        settings.insert("otherFields".to_string(), Value::Object(other));
    }

    let provider_id = format!("{}{}", v.provider_prefix, uuid::Uuid::new_v4());
    let name = format!(
        "{} {}",
        v.import_label,
        chrono::Local::now().format("%Y-%m-%d %H:%M")
    );
    let settings_config =
        serde_json::to_value(&settings).unwrap_or_else(|_| serde_json::json!({}));

    let provider = crate::provider::Provider {
        id: provider_id,
        name,
        settings_config,
        website_url: None,
        category: Some(v.category.to_string()),
        created_at: Some(chrono::Utc::now().timestamp_millis()),
        sort_index: None,
        notes: None,
        meta: None,
        icon: None,
        icon_color: None,
        in_failover_queue: false,
    };

    state.db.save_provider("opencode", &provider)?;
    state
        .db
        .set_omo_provider_current("opencode", &provider.id, v.category)?;
    Self::write_config_to_file(state, v)?;
    Ok(provider)
}

pub fn validate_proxy_provider(provider: &Provider) -> Result<(), AppError> {
    if is_official_provider(provider) {
        return Ok(());
    }

    if !provider.settings_config.is_object() {
        return Err(AppError::localized(
            "claude_desktop.provider.settings_not_object",
            "Claude Desktop 本地路由供应商配置必须是 JSON 对象",
            "Claude Desktop proxy provider configuration must be a JSON object",
        ));
    }

    if let Some(meta) = provider.meta.as_ref() {
        if let Some(api_format) = meta.api_format.as_deref() {
            if !matches!(
                api_format,
                "" | "anthropic" | "openai_chat" | "openai_responses" | "gemini_native"
            ) {
                return Err(AppError::localized(
                    "claude_desktop.provider.api_format_unsupported",
                    format!("Claude Desktop 本地路由模式不支持 API 格式: {api_format}"),
                    format!("Claude Desktop proxy mode does not support API format: {api_format}"),
                ));
            }
        }
    }

    proxy_model_routes(provider)?;

    if !has_proxy_base_url_and_key(provider) {
        return Err(AppError::localized(
            "claude_desktop.provider.credentials_missing",
            "Claude Desktop 本地路由供应商缺少 Base URL 或 API Key",
            "Claude Desktop proxy provider is missing Base URL or API key",
        ));
    }

    Ok(())
}

fn mimo_anthropic_proxy_provider(id: &str) -> Provider {
    let mut provider = direct_provider(id);
    provider.name = "MiMo Proxy".to_string();
    provider.settings_config = json!({
        "env": {
            "ANTHROPIC_BASE_URL": "https://api.xiaomimimo.com/anthropic",
            "ANTHROPIC_AUTH_TOKEN": "test-token"
        }
    });
    provider.meta = Some(ProviderMeta {
        claude_desktop_mode: Some(ClaudeDesktopMode::Proxy),
